  return Promise.resolve().then(() => {
    if (typeof token !== 'string' || typeof secret !== 'string' || secret.length === 0 ||
        !Number.isSafeInteger(currentSecond) || currentSecond < 0) {
      throw new TypeError('Invalid verification input');
