'use strict';

const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const verifyVoucher = require('./solution');

assert.equal(typeof verifyVoucher, 'function');

function signBody(body, secret) {
  return crypto.createHmac('sha256', secret).update(body).digest('base64url');
}

function tokenFor(payload, secret) {
  const body = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url');
  return `${body}.${signBody(body, secret)}`;
}

function tokenForBody(body, secret) {
  return `${body}.${signBody(body, secret)}`;
}

function returnedPromise(...args) {
  let result;
  assert.doesNotThrow(() => { result = verifyVoucher(...args); });
  assert.ok(result instanceof Promise, 'verifyVoucher must return a Promise');
  return result;
}

async function expectRejected(args, check) {
  const promise = returnedPromise(...args);
  await assert.rejects(promise, check);
}

(async () => {
  const secret = 'correct horse battery staple';
  const payload = {
    subject: 'user-42',
    expiresAt: 200,
    permissions: ['read'],
    metadata: { region: 'in' }
  };
  const token = tokenFor(payload, secret);

  const first = await returnedPromise(token, secret, 199);
  const second = await returnedPromise(token, secret, 0);
  assert.deepEqual(first, payload);
  assert.deepEqual(second, payload);
  assert.notStrictEqual(first, second);
  assert.notStrictEqual(first.permissions, second.permissions);
  assert.notStrictEqual(first.metadata, second.metadata);

  await expectRejected([tokenFor({ subject: 'u', expiresAt: 10 }, secret), secret, 10], (error) => {
    assert.ok(error instanceof Error);
    assert.equal(error.code, 'VOUCHER_EXPIRED');
    return true;
  });
  await expectRejected([tokenFor({ subject: 'u', expiresAt: 9 }, secret), secret, 10], (error) => {
    assert.equal(error.code, 'VOUCHER_EXPIRED');
    return true;
  });

  const originalSignature = token.split('.')[1];
  const wrongSignature = `${originalSignature[0] === 'A' ? 'B' : 'A'}${originalSignature.slice(1)}`;
  await expectRejected([`${token.split('.')[0]}.${wrongSignature}`, secret, 0]);
  await expectRejected([token, 'wrong secret', 0]);

  const invalidPayloads = [
    [], null, {}, { subject: '', expiresAt: 2 }, { subject: 3, expiresAt: 2 },
    { subject: 'u', expiresAt: -1 }, { subject: 'u', expiresAt: 1.5 },
    { subject: 'u', expiresAt: Number.MAX_SAFE_INTEGER + 1 },
    { subject: 'u', expiresAt: '2' }
  ];
  for (const invalid of invalidPayloads) {
    await expectRejected([tokenFor(invalid, secret), secret, 0]);
  }

  const invalidJsonBody = Buffer.from('{not json', 'utf8').toString('base64url');
  await expectRejected([tokenForBody(invalidJsonBody, secret), secret, 0]);
  await expectRejected([tokenForBody('*', secret), secret, 0]);
  await expectRejected(['', secret, 0]);
  await expectRejected(['abc', secret, 0]);
  await expectRejected(['a.b.c', secret, 0]);
  await expectRejected(['.', secret, 0]);
  await expectRejected([null, secret, 0]);

  for (const args of [
    [token, '', 0], [token, null, 0], [token, secret, -1], [token, secret, 1.2],
    [token, secret, Number.MAX_SAFE_INTEGER + 1], [token, secret, '0'],
    [token, secret, NaN], [token, secret, Infinity]
  ]) {
    await expectRejected(args, TypeError);
  }
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

